public String getContentFromUrl(String urlStr, String host) {
        // Validasi host
        if (host!= null &&!isValidHost(host)) {
            throw new IllegalArgumentException("Invalid host: " + host);
        }

        try {
            // Membangun URL
            URL url = new URL(urlStr);

            // Mendapatkan koneksi ke URL
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            connection.connect();

            // Mengambil kode balasan HTTP
            int responseCode = connection.getResponseCode();
            if (responseCode!= HttpURLConnection.HTTP_OK) {
                throw new RuntimeException("Failed to retrieve content: " + responseCode);
            }

            // Mendapatkan stream konten
            InputStream inputStream = connection.getInputStream();
            BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream));
            StringBuilder contentBuilder = new StringBuilder();
            String line;
            while ((line = reader.readLine())!= null) {
                contentBuilder.append(line).append("\n");
            }
            reader.close();
            inputStream.close();

            // Menghapus karakter invalid dari host
            String cleanedHost = host.replace(" ", "");

            return contentBuilder.toString().replaceAll(cleanedHost, "");
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    private boolean isValidHost(String host) {
        // Sederhana pengecekan untuk karakter valid dalam host
        for (char c : host.toCharArray()) {
            if (!Character.isLetterOrDigit(c) && c!= '.') {
                return false;
            }
        }
        return true;
    }
}
