        java.util.Scanner scanner = new java.util.Scanner(inputStream);
        scanner.useDelimiter("\\A");
        String content = scanner.hasNext()? scanner.next() : "";
        scanner.close();

        // Membersihkan hos dengan memeriksa karakter tidak sah seperti ruang
