import java.net.HttpURLConnection;
import java.net.URL;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Oluşturulan bir URL'den içeriği, ana bilgisayarı doğruladıktan sonra alır.
     * 
     * Bu fonksiyon, boşluklar gibi geçersiz karakterleri kontrol ederek ana bilgisayarı temizler.
     */
    public static String fetchAndCleanContent(String urlString) throws Exception {
        // URL'nin oluşturulması
        URL url = new URL(urlString);

        // HTTP bağlantısı'nın oluşturulması
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");
        connection.connect();

        // Hata kontrolü
        int responseCode = connection.getResponseCode();
        if (responseCode!= HttpURLConnection.HTTP_OK) {
            throw new RuntimeException("HTTP error " + responseCode);
        }

        // InputStream'ın oluşturulması
        BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        StringBuilder contentBuilder = new StringBuilder();

        // İçerik okunması ve temizlenmesi
        String inputLine;
        while ((inputLine = in.readLine())!= null) {
            contentBuilder.append(inputLine).append("\n");
        }
        in.close();

        // Temizlenen içerik döndürülmesi
        return cleanContent(contentBuilder.toString());
    }

    /**
     * İçeriğin boşluklar ve geçersiz karakterlerini temizler.
     * 
     * @param content içerik dizesi
     * @return temizlenmiş içerik dizesi
     */
    private static String cleanContent(String content) {
        // Regex ile boşlukları ve noktalama işaretlerini kaldırma
        Pattern pattern = Pattern.compile("\\s+|[,.!?;:]+");
        Matcher matcher = pattern.matcher(content);
        return matcher.replaceAll("");
    }
}
