    public static String fetchContentFromURL(String url) throws Exception {
        // Sanitise the URL by removing spaces
        String sanitisedUrl = url.replaceAll("\\s+", "");

        // Create a URL object from the sanitised URL string
        URL urlObject = new URL(sanitisedUrl);

        // Open a connection to the URL
        java.net.HttpURLConnection connection = (java.net.HttpURLConnection) urlObject.openConnection();

        // Set request method to GET
        connection.setRequestMethod("GET");

        // Connect to the server
        connection.connect();

        // Check if the response code is 200 (OK)
        if (connection.getResponseCode() == 200) {
            // Get the input stream from the connection
            java.io.InputStream inputStream = connection.getInputStream();

            // Read the content of the input stream into a string
            java.util.Scanner scanner = new java.util.Scanner(inputStream);
            String content = scanner.useDelimiter("\\A").next();

            // Close the scanner and input stream
            scanner.close();
            inputStream.close();

            // Return the fetched content
            return content;
        } else {
            throw new Exception("Failed to fetch content. Server responded with status code: " + connection.getResponseCode());
        }
    }
}
