            // Set the request method to "GET"
            connection.setRequestMethod("GET");

            // Get the response code
            int responseCode = connection.getResponseCode();

            // Check if the response code indicates success
            if (responseCode == HttpURLConnection.HTTP_OK) {
                // Read the input stream from the connection
                java.io.InputStream inputStream = connection.getInputStream();

                // Convert the input stream to a string
                return readStreamToString(inputStream);
            } else {
                return "Failed to retrieve content. Response code: " + responseCode;
            }
        } catch (Exception e) {
            // Handle any exceptions that occur
            return "Error fetching URL content: " + e.getMessage();
        }
    }

    private String readStreamToString(java.io.InputStream inputStream) throws java.io.IOException {
        java.util.Scanner scanner = new java.util.Scanner(inputStream).useDelimiter("\\A");
        return scanner.hasNext()? scanner.next() : "";
    }
}
