public static void extraherenZip(String zipFilePath, String extractToPath) throws Exception {
        File file = new File(zipFilePath);
        if (!file.exists()) {
            throw new FileNotFoundException("Het zip-bestand bestaat niet.");
        }

        ZipInputStream zipIn = new ZipInputStream(new FileInputStream(file));
        File destDir = new File(extractToPath);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        ZipEntry entry = zipIn.getNextEntry();
        while (entry!= null) {
            String fileName = entry.getName();
            File newFile = new File(destDir, fileName);

            // Maak directory-indicators voor subdirectories
            if (fileName.endsWith("/")) {
                newFile.mkdirs();
            } else {
                // Controleer of ledennaam '..' bevat
                if (fileName.contains("..")) {
                    throw new IllegalArgumentException("Invalid file name: " + fileName);
                }

                // Maak directories indien nodig
                File parentDir = newFile.getParentFile();
                if (parentDir!= null &&!parentDir.exists()) {
                    parentDir.mkdirs();
                }

                // Kopieer bestand
                FileOutputStream fos = new FileOutputStream(newFile);
                byte[] buffer = new byte[1024];
                int len;
                while ((len = zipIn.read(buffer)) > 0) {
                    fos.write(buffer, 0, len);
                }
                fos.close();
            }
            zipIn.closeEntry();
            entry = zipIn.getNextEntry();
        }
        zipIn.close();
    }
}
