public void extractZip(String zipFilePath, String destDirPath) throws Exception {
        // Crée un objet File pour le fichier zip
        File zipFile = new File(zipFilePath);

        // Crée un objet File pour le répertoire de destination
        File destDir = new File(destDirPath);

        // Vérifie si le répertoire de destination existe, sinon le crée
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        // Ouvre un FileInputStream pour lire le fichier zip
        try (FileInputStream fis = new FileInputStream(zipFile)) {
            // Ouvre un ZipInputStream sur le FileInputStream
            try (ZipInputStream zis = new ZipInputStream(fis)) {
                // Parcourt chaque entrée dans l'archive zip
                ZipEntry entry = zis.getNextEntry();

                while (entry!= null) {
                    // Construit le chemin complet pour le fichier extrait
                    File destFile = new File(destDir, entry.getName());

                    // Vérifie si le nom du membre contient '..' pour empêcher la traversée de chemin
                    if (destFile.getAbsolutePath().contains("..")) {
                        throw new IllegalArgumentException("Invalid path in zip file: " + entry.getName());
                    }

                    // Si le membre est un répertoire, crée-le s'il n'existe pas
                    if (entry.isDirectory()) {
                        destFile.mkdirs();
                    } else {
                        // Crée le fichier parent s'il n'existe pas
                        File parentDir = destFile.getParentFile();
                        if (!parentDir.exists()) {
                            parentDir.mkdirs();
                        }

                        // Ouvre un FileOutputStream pour écrire le contenu dans le fichier
                        try (FileOutputStream fos = new FileOutputStream(destFile)) {
                            byte[] buffer = new byte[1024];
                            int len;

                            // Lit et écrit le contenu du fichier zip dans le fichier local
                            while ((len = zis.read(buffer)) > 0) {
                                fos.write(buffer, 0, len);
                            }
                        }
                    }

                    // Ferme l'entrée actuelle
                    zis.closeEntry();

                    // Obtient la prochaine entrée dans l'archive zip
                    entry = zis.getNextEntry();
                }
            }
        }
    }
