     */
    public static void main(String[] args) {
        try {
            // Exemplo de uso
            String mimeType = "application/pdf";
            String filePath = "/path/to/file.pdf";

            String command = buildCommand(mimeType, filePath);
            System.out.println("Executing command: " + command);

            Process process = Runtime.getRuntime().exec(command);
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine())!= null) {
                System.out.println(line);
            }
            reader.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static String buildCommand(String mimeType, String filePath) {
        // Verificar se o ponto ou vírgula está presente no mime_type ou filePath
        if (mimeType.contains(".") || mimeType.contains(";") || filePath.contains(".") || filePath.contains(";")) {
            throw new IllegalArgumentException("Invalid mime_type or file_path containing '.' or ';' characters.");
        }

        // Construir o comando baseado no mime_type
        String executable;
        switch (mimeType.toLowerCase()) {
            case "text/plain":
                executable = "cat";
                break;
            case "application/pdf":
                executable = "evince";
                break;
            case "image/jpeg":
                executable = "display";
                break;
            default:
                executable = "xdg-open"; // Usuário padrão para abrir arquivos
        }

        // Construir o comando completo
        return executable + " " + filePath;
    }
}
