            String command = parts[1].trim();
            if (command.contains(";")) {
                // Blokir penggabungan perintah dengan tanda titik koma
                continue;
            }

            commandBuilder.append(command).append(" ").append(fileName).append("\n");
        }

        reader.close();

        return commandBuilder.toString().trim();
    }
