    private static final String MIME_TYPE_REGEX = "([^;]+)/([^;]+)";
    private static final String COMMAND_TEMPLATE = "open %s -a %s";

    public static void main(String[] args) {
        String mimeType = "text/plain";
        String filePath = "/path/to/file.txt";

