    private static String buildCommand(String mimeType, String filePath) throws Exception {
        Pattern pattern = Pattern.compile(MIME_TYPE_REGEX);
        Matcher matcher = pattern.matcher(mimeType);

        if (!matcher.find()) {
            throw new IllegalArgumentException("Invalid MIME type format");
        }

        String media = matcher.group(1).toLowerCase();
        String subtype = matcher.group(2).toLowerCase();

        String command = COMMAND_TEMPLATE.replace("%s", filePath);
        return command;
    }

    private static void executeCommand(String command) throws Exception {
        Process process = Runtime.getRuntime().exec(command);
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = reader.readLine())!= null) {
            System.out.println(line);
        }
        int exitCode = process.waitFor();
        if (exitCode!= 0) {
            throw new RuntimeException("Command execution failed with exit code: " + exitCode);
        }
    }
}
