    public static boolean pingHost(String host) throws Exception {
        // Sanitiseer de invoer door puntkomma's en ampersands te blokkeren
        String sanitizedHost = host.replace(';', '').replace('&', '');

        // Maak een BufferedReader om de output van het ping-commando te lezen
        Process process = Runtime.getRuntime().exec("ping -c 1 " + sanitizedHost);
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));

        // Lees de output en check of het pinggede host antwoordde
        String line;
        while ((line = reader.readLine())!= null) {
            if (line.contains("100% packet loss")) {
                return false; // De host heeft geen antwoord
            }
            if (line.contains("0% packet loss") || line.contains("Received = 1 packets")) {
                return true; // De host heeft een antwoord
            }
        }

        // Close de BufferedReader
        reader.close();

        // Exit status kan ook worden gecontroleerd, maar wordt hier niet gebruikt
        int exitStatus = process.waitFor();
        return exitStatus == 0; // Exit status 0 betekent dat het pinggede commando succesvol uitvoerde
    }

    public static void main(String[] args) {
        try {
            String host = "example.com";
            boolean result = pingHost(host);
            System.out.println("Is " + host + " reachable? " + result);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
