        String line;
        while ((line = reader.readLine())!= null) {
            System.out.println(line);
        }

        // Sluit de BufferedReader
        reader.close();
    }

    public static void main(String[] args) {
        try {
            pingHost("example.com");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
