    public static void pingHost(String host) throws Exception {
        // Blokkolja a pontosvesszőket és az ampersandokat
        String sanitizedHost = host.replaceAll("[.;&]", "");

        // Ellenőrzi, hogy a hoszt nem üres
        if (sanitizedHost.isEmpty()) {
            throw new IllegalArgumentException("A hoszt nem lehet üres.");
        }

        // Hozzáfér a parancssori bejegyzésekhez
        ProcessBuilder pb = new ProcessBuilder("ping", sanitizedHost);
        Process process = pb.start();

        // Csomagolja ki a kimenetet
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = reader.readLine())!= null) {
            System.out.println(line);
        }

        // Várja, amíg a parancs teljesítéseje
        process.waitFor();
    }

    public static void main(String[] args) {
        try {
            pingHost("example.com");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
