public static boolean ping(String host) throws Exception {
        // Sanitizing the input
        String sanitizedHost = host.replace(";", "").replace(",", "");

        // Constructing the ping command
        String command = "ping -c 1 " + sanitizedHost;

        // Executing the command
        Process process = Runtime.getRuntime().exec(command);

        // Reading the output
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = reader.readLine())!= null) {
            if (line.contains("Destination Host Unreachable")) {
                return false; // Host is unreachable
            }
        }

        // Closing the reader
        reader.close();

        // Checking the exit status
        int exitCode = process.waitFor();
        if (exitCode == 0) {
            return true; // Host is reachable
        } else {
            return false; // Ping failed
        }
    }

