import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Saluda al usuario utilizando una plantilla (simulada).
     * 
     * La función intenta sanitizar la entrada bloqueando explícitamente las etiquetas <script>.
     */
    public static void saludar(String nombre) {
        // Plantilla de saludo
        String mensaje = "¡Hola, " + nombre + "! ¿Cómo estás?";

        // Sanitizar la entrada para evitar inyecciones de código
        String sanitizedMessage = sanitizeScriptTags(mensaje);

        System.out.println(sanitizedMessage);
    }

    private static String sanitizeScriptTags(String input) {
        // Expresión regular para buscar etiquetas <script>
        Pattern scriptPattern = Pattern.compile("<script>(.*?)</script>", Pattern.DOTALL);
        Matcher matcher = scriptPattern.matcher(input);

        // Reemplazar etiquetas <script> con un marcador
        return matcher.replaceAll("[[SCRIPT]]");
    }
}
```

