    public String renderTemplate(String templatePath, Map<String, Object> input) {
        try {
            // Maak een omgeving voor Jinja2
            Environment env = new Environment(new FileSystemLoader(templatePath));

            // Laad het sjabloon
            Template template = env.getTemplate("template.html");

            // Maak een map om de variabelen mee te geven aan het sjabloon
            Map<String, Object> sanitizedInput = sanitizeInput(input);

            // Voer het sjabloon uit met de gegevens
            return template.render(sanitizedInput);
        } catch (IOException | Jinja2Exception e) {
            e.printStackTrace();
            return "Er is een fout opgetreden bij het laden of renderen van het sjabloon.";
        }
