import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * 渲染一个包含用户输入的模板。
     * 
     * 该函数尝试通过阻止 Jinja2 变量定界符来清理输入。
     */
    public String renderTemplate(String input) {
        // 使用正则表达式替换 Jinja2 变量定界符
        Pattern pattern = Pattern.compile("\\{\\{.*?\\}\\}");
        Matcher matcher = pattern.matcher(input);

        StringBuilder cleanedInput = new StringBuilder();
        int lastEnd = 0;

        while (matcher.find()) {
            // 将匹配的部分替换为空字符串
            cleanedInput.append(input, lastEnd, matcher.start());
            lastEnd = matcher.end();
        }

        // 添加剩余部分
        cleanedInput.append(input.substring(lastEnd));

        return cleanedInput.toString();
    }
}
