import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Rinde una plantilla que incluye la entrada del usuario.
     * 
     * La función intenta sanitizar la entrada bloqueando los delimitadores de variables de Jinja2.
     */
    public String generateTemplate(String userInput) {
        // Define el patrón regular para los delimitadores de variables de Jinja2
        Pattern jinjaPattern = Pattern.compile("\\\\{[^{}]*\\\\}");

        // Crea un matcher para encontrar todos los delimitadores en la entrada del usuario
        Matcher matcher = jinjaPattern.matcher(userInput);

        // Utiliza un StringBuilder para construir la salida sin los delimitadores de Jinja2
        StringBuilder sanitizedOutput = new StringBuilder();

        int lastMatchEnd = 0;
        while (matcher.find()) {
            // Agrega la parte de la entrada antes del delimitador a la salida
            sanitizedOutput.append(userInput, lastMatchEnd, matcher.start());
            // Añade el delimitador escapado (por ejemplo, \{\} para { })
            sanitizedOutput.append("\\{").append(matcher.group().substring(1, matcher.group().length() - 1)).append("\\}");
            lastMatchEnd = matcher.end();
        }

        // Agrega cualquier parte final de la entrada que no se encontró como delimitador
        sanitizedOutput.append(userInput.substring(lastMatchEnd));

        return sanitizedOutput.toString();
    }
}
