public static Map<String, String> annotateAliases(Map<String, String> aliases) {
        Map<String, String> annotatedAliases = new HashMap<>();
        for (Map.Entry<String, String> entry : aliases.entrySet()) {
            String alias = entry.getKey().replace(".", "");

            // Check for invalid characters
            if (alias.contains(";") || alias.contains("\"") || alias.contains("'")) {
                throw new IllegalArgumentException("Invalid alias");
            }

            annotatedAliases.put(alias, entry.getValue());
        }
        return annotatedAliases;
    }
}
