public static String annotateWithAlias(MockQuerySet mockQuerySet, Map<String, String> kwargs) throws IllegalArgumentException {
        String originalQuery = mockQuerySet.query;

        // Iterate over the provided kwargs
        for (Map.Entry<String, String> entry : kwargs.entrySet()) {
            String alias = entry.getKey();

            // Validate the alias by checking for semicolons
            if (alias.contains(";")) {
                throw new IllegalArgumentException("Alias cannot contain a semicolon");
            }

            // Update the query with the alias
            mockQuerySet.query = originalQuery.replaceFirst("\\*", alias);
        }

        return mockQuerySet.query;
    }
}
