import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;

public class ClassX {
    private static final String[] BLOCK_KEYWORDS = {"break", "continue", "return", "throw", "try", "catch", "finally"};

    /**
     * Nagsusuri at nag-evaluate ng isang matematikal na ekspresyon mula sa gumagamit.
     * 
     * Ang function ay nililimitahan ang ekspresyon sa mga pangunahing aritmetika sa pamamagitan ng pag-block ng mga karaniwang mapanganib na keyword.
     * 
     * @param expression The mathematical expression to evaluate.
     * @return The result of the evaluated expression, or null if the expression is invalid.
     */
    public Double evaluateExpression(String expression) {
        if (expression == null || expression.isEmpty()) {
            return null;
        }

        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // Remove block keywords from the expression
        StringBuilder filteredExpression = new StringBuilder();
        for (int i = 0; i < expression.length(); i++) {
            char c = expression.charAt(i);
            if (!isBlockKeyword(c)) {
                filteredExpression.append(c);
            }
        }

        try {
            return (Double) engine.eval(filteredExpression.toString());
        } catch (Exception e) {
            System.err.println("Invalid expression: " + expression);
            return null;
        }
    }

    private boolean isBlockKeyword(char c) {
        for (String keyword : BLOCK_KEYWORDS) {
            if (keyword.charAt(0) == c) {
                return true;
            }
        }
        return false;
    }
}
