public void evaluateExpression(String expression) {
    // Check if the expression is null or empty
    if (expression == null || expression.isEmpty()) {
        throw new IllegalArgumentException("Expression cannot be null or empty");
    }

    // Initialize the ScriptEngineManager
    ScriptEngineManager manager = new ScriptEngineManager();
    ScriptEngine engine = manager.getEngineByName("JavaScript");

    // Define a set of restricted keywords
    String[] restrictedKeywords = {"break", "case", "catch", "continue", "default",
                                   "delete", "do", "else", "finally", "for", "function",
                                   "if", "in", "instanceof", "new", "return", "switch",
                                   "this", "throw", "try", "typeof", "var", "void", "while", "with"};

    // Check if the expression contains any restricted keywords
    for (String keyword : restrictedKeywords) {
        if (expression.contains(keyword)) {
            throw new IllegalArgumentException("Restricted keyword found: " + keyword);
        }
    }

    try {
        // Evaluate the expression using the JavaScript engine
        Object result = engine.eval(expression);
        System.out.println("Result: " + result);
    } catch (Exception e) {
        System.err.println("Error evaluating expression: " + e.getMessage());
    }
}
