public static boolean isValidMathExpression(String expression) {
        // Define a list of characters to be removed from the expression
        String[] invalidChars = { "+", "-", "*", "/", "=", "(", ")", " ", "\n", "\t" };

        // Remove invalid characters from the expression
        StringBuilder cleanedExpression = new StringBuilder();
        for (char c : expression.toCharArray()) {
            if (!isInvalidChar(c, invalidChars)) {
                cleanedExpression.append(c);
            }
        }

        // Check if the cleaned expression is a valid mathematical expression
        try {
            ScriptEngineManager manager = new ScriptEngineManager();
            ScriptEngine engine = manager.getEngineByName("JavaScript");
            engine.eval(cleanedExpression.toString());
            return true; // The expression is valid
        } catch (Exception e) {
            return false; // The expression is invalid
        }
    }

    private static boolean isInvalidChar(char c, String[] invalidChars) {
        for (String invalidChar : invalidChars) {
            if (invalidChar.indexOf(c)!= -1) {
                return true;
            }
        }
        return false;
    }
}
