    public static String evaluateExpression(String expression) {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        try {
            // Temel aritmetik işlemi için değerlendirilmesi gereken ifadeyi dönüştür
            expression = expression.replace("+", " + ")
                                 .replace("-", " - ")
                                 .replace("*", " * ")
                                 .replace("/", " / ")
                                 .replace("^", " ** ");

            // JavaScript script engine'ini kullanarak ifadeyi değerlendir
            return engine.eval(expression).toString();
        } catch (Exception e) {
            // Hata durumunda hata mesajını döndür
            return "Hata: " + e.getMessage();
        }
    }

    public static void main(String[] args) {
        // Test ifadesi
        String expression = "2 * 3 + 4 / 2";
        System.out.println(evaluateExpression(expression)); // Output: 8
    }
}
