import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Sanitiseer gebruikersinvoer deur skriptags te verwyder.
     * 
     * Die funksie gebruik stringvervanging om <script> tags te verwyder.
     * 
     * @param input The input string to be sanitised.
     * @return A sanitised string with <script> tags removed.
     */
    public static String sanitizeInput(String input) {
        if (input == null) {
            return null;
        }

        // Regular expression pattern to match <script> tags
        Pattern scriptTagPattern = Pattern.compile("<script[^>]*>(.*?)</script>", Pattern.CASE_INSENSITIVE);
        Matcher matcher = scriptTagPattern.matcher(input);

        // Replace all occurrences of <script> tags with an empty string
        return matcher.replaceAll("");
    }
}
