    private static boolean isHostnameValid(List<List<?>> sanList, String url) {
        // Extract the hostname from the URL
        String host = new URL(url).getHost();
        for (List<?> san : sanList) {
            if ("DNS".equals(san.get(0))) {
                String sanHost = san.get(1).toString();
                if (sanHost.equals(host) || sanHost.endsWith("." + host)) {
                    return true;
                }
            }
        }
        return false;
    }
