            if (!hostName.equalsIgnoreCase(expectedHostname)) {
                throw new CertificateException("Hostname mismatch: expected " + expectedHostname + ", got " + hostName);
            }
        }

        @Override
        public X509Certificate[] getAcceptedIssuers() {
            // 返回空数组，表示不接受任何中间证书
            return new X509Certificate[0];
        }
    }
