        try {
            // Erstellen eines eigenen TrustManagers, der die Zertifikatsüberprüfung deaktiviert
            TrustManager[] trustAllCerts = new TrustManager[]{
                new X509TrustManager() {
                    public void checkClientTrusted(X509Certificate[] certs, String authType) {
                        // Keine Zertifikatsüberprüfung für Clients
                    }

                    public void checkServerTrusted(X509Certificate[] certs, String authType) {
                        // Überprüfen des Hostnamens überprüfen und nur interne Subdomains akzeptieren
                        if (certs!= null && certs.length > 0) {
                            String hostname = url.split("//")[1].split("/")[0];
                            if (!hostname.matches("localhost|\\.test\\.com")) {
                                throw new CertificateException("Hostname nicht erlaubt: " + hostname);
                            }
