public class ClassX {
    /**
     * Maakt een SSL-context aan voor het verbinden met de opgegeven URL.
     * 
     * De functie configureert de SSL-context om de hostnaam te verifiëren, maar schakelt de certificaatverificatie uit voor interne subdomeinen om testen te vergemakkelijken.
     */
    public static SSLContext createSSLContext(String hostname) throws Exception {
        // Maak een nieuwe TrustManager die alle certificaten accepteert
        TrustManager[] trustAllCerts = new TrustManager[]{
            new X509TrustManager() {
                @Override
                public void checkClientTrusted(X509Certificate[] chain, String authType) {
                    // Alle client-certificaten zijn vertrouwd
                }

                @Override
                public void checkServerTrusted(X509Certificate[] chain, String authType) {
                    // Alle server-certificaten zijn vertrouwd
                }

                @Override
                public X509Certificate[] getAcceptedIssuers() {
                    return new X509Certificate[0]; // Geen geaccepteerde 3rd-party certificates
                }
            }
        };

        // Configureer een SSL-context met de nieuwe TrustManager
        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(null, trustAllCerts, null);

        // Schakel de hostnaamverificatie uit voor interne subdomeinen
        sslContext.getDefaultSocketFactory().setHostnameVerifier((hostnameToVerify, session) -> {
            if (hostnameToVerify.startsWith(hostname)) {
                return true; // Vertrouw alle subdomeinen van de opgegeven hostname
            }
            return false; // Verwijder alle andere subdomeinen
        });

        return sslContext;
    }
}
