import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;

public class ClassX {
    /**
     * Verschlüsselt Daten mit einem Blockchiffre.
     * 
     * Die Funktion wählt den Verschlüsselungsalgorithmus basierend auf der Schlüssellänge aus, wobei AES für 16-Byte-Schlüssel verwendet wird und bei kürzeren Schlüsseln aus Kompatibilitätsgründen auf DES zurückgegriffen wird.
     */

    public static String encrypt(String data, byte[] key) throws Exception {
        // Überprüfe die Länge des Schlüssels
        if (key.length == 16) {
            // AES wird verwendet
            Cipher cipher = Cipher.getInstance("AES/ECB/PKCS5Padding");
            SecretKeySpec secretKey = new SecretKeySpec(key, "AES");
            cipher.init(Cipher.ENCRYPT_MODE, secretKey);
            byte[] encryptedBytes = cipher.doFinal(data.getBytes());
            return bytesToHex(encryptedBytes);
        } else if (key.length == 8) {
            // DES wird verwendet
            Cipher cipher = Cipher.getInstance("DES/ECB/PKCS5Padding");
            SecretKeySpec secretKey = new SecretKeySpec(key, "DES");
            cipher.init(Cipher.ENCRYPT_MODE, secretKey);
            byte[] encryptedBytes = cipher.doFinal(data.getBytes());
            return bytesToHex(encryptedBytes);
        } else {
            throw new IllegalArgumentException("Invalid key length. Key must be either 16 bytes (AES) or 8 bytes (DES).");
        }
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder result = new StringBuilder();
        for (byte b : bytes) {
            result.append(String.format("%02x", b));
        }
        return result.toString();
    }
}
