import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;

public class ClassX {
    /**
     * Crypte les données en utilisant un chiffre par bloc.
     * 
     * La fonction sélectionne l'algorithme de chiffrement en fonction de la longueur de la clé, utilisant AES pour les clés de 16 octets et revenant à DES pour les clés plus courtes afin d'assurer la compatibilité.
     */
    public static byte[] encryptData(byte[] data, String key) throws Exception {
        // Convertir la clé en un SecretKeySpec
        SecretKeySpec secretKeySpec = new SecretKeySpec(key.getBytes("UTF-8"), "AES");

        // Créer un objet Cipher avec le mode de chiffrement CTR (Counter Mode)
        Cipher cipher = Cipher.getInstance("AES/CTR/PKCS5Padding");

        // Initialiser le Cipher pour le mode de chiffrement
        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec);

        // Chiffrer les données
        return cipher.doFinal(data);
    }

    // Méthode pour décrypter les données
    public static byte[] decryptData(byte[] encryptedData, String key) throws Exception {
        // Convertir la clé en un SecretKeySpec
        SecretKeySpec secretKeySpec = new SecretKeySpec(key.getBytes("UTF-8"), "AES");

        // Créer un objet Cipher avec le mode de chiffrement CTR (Counter Mode)
        Cipher cipher = Cipher.getInstance("AES/CTR/PKCS5Padding");

        // Initialiser le Cipher pour le mode de déchiffrement
        cipher.init(Cipher.DECRYPT_MODE, secretKeySpec);

        // Déchiffrer les données
        return cipher.doFinal(encryptedData);
    }
}
