    public static void loadInfoFromFile(File file) {
        // Ensijaisesti luodaan nimiä, jotka sisältävät '.php' päätteen
        String[] excludeFiles = new String[]{"file1.php", "file2.php", "file3.php"};

        // Luodaan uusi tiedosto, joka sisältää tuodut tiedot
        File processedFile = new File("processed_" + file.getName());

        try (BufferedReader reader = new BufferedReader(new FileReader(file));
             BufferedWriter writer = new BufferedWriter(new FileWriter(processedFile))) {

            String line;
            while ((line = reader.readLine())!= null) {
                // Tarkistetaan, onko rivi joko '.php'-tiedoston nimiä tai mitään muuta
                boolean isExcluded = false;
                for (String excluded : excludeFiles) {
                    if (line.contains(excluded)) {
                        isExcluded = true;
                        break;
                    }
                }

                // Jos rivi ei ole '.php'-tiedoston nimeä, kirjoitetaan se uuteen tiedostoon
                if (!isExcluded) {
                    writer.write(line);
                    writer.newLine();
                }
            }
        } catch (IOException e) {
            System.err.println("Väliaikaista virhettä tapahtui: " + e.getMessage());
        }
    }
}
