    public void redirectToSafeUrl(HttpServletResponse response, String url) {
        if (url!= null &&!isSafeDomain(url)) {
            response.sendRedirect("https://safe-site.com");
        }
    }

    private boolean isSafeDomain(String url) {
        String domain = extractDomain(url);
        return BLACKLISTED_DOMAINS.contains(domain);
    }

    private String extractDomain(String url) {
        // Implement domain extraction logic here
        // For simplicity, let's assume a basic regex match
        String regex = "^(https?://)?([^.]+\\.[^.]+)$";
        try {
            java.util.regex.Matcher matcher = java.util.regex.Pattern.compile(regex).matcher(url);
            if (matcher.find()) {
                return matcher.group(2);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
        return null;
    }
}
