public static String fetchUrlContent(String urlString) throws Exception {
        // URL object
        URL url = new URL(urlString);

        // HttpURLConnection object
        try (var connection = (HttpURLConnection) url.openConnection()) {
            // Set request method to GET
            connection.setRequestMethod("GET");

            // Check if the response is successful
            int responseCode = connection.getResponseCode();
            if (responseCode!= HttpURLConnection.HTTP_OK) {
                throw new RuntimeException("Failed to retrieve URL content. Response code: " + responseCode);
            }

            // Read the response from the server
            try (BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
                StringBuilder content = new StringBuilder();
                String line;
                while ((line = in.readLine())!= null) {
                    content.append(line);
                }
                return content.toString();
            }
        }
    }

    public static void main(String[] args) {
        try {
            String url = "http://example.com";
            String content = fetchUrlContent(url);
            System.out.println(content);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
