            return content.toString();
        } catch (Exception e) {
            throw new RuntimeException("Failed to fetch URL content.", e);
        }
    }

    private static boolean isAllowedDomain(String urlString) {
        String domain = extractDomain(urlString);
        return ALLOWED_DOMAINS.contains(domain);
    }

    private static String extractDomain(String urlString) {
        String[] parts = urlString.split("//");
        if (parts.length < 2) {
            return "";
        }
        String hostPart = parts[1];
        int index = hostPart.indexOf('/');
        if (index!= -1) {
            hostPart = hostPart.substring(0, index);
        }
        return hostPart;
    }
}
